package cli

import (
	"errors"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/spf13/cobra"
)

// newUnderstandGroupCmd builds `entire understand` and registers its
// subcommands. Subcommands are added incrementally as they're implemented;
// see docs/prompts/entire-understand-command.md for the full spec.
func newUnderstandGroupCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "understand",
		Short: "Native repo-understanding subsystem (graph + history + semantic)",
		Long: `Operations that fuse structural code analysis with checkpoint history into a
single navigable graph.

Commands:
  status    Report build state, freshness, and provider used for semantics
  build     Run the full understanding pipeline (scan → structure → history → semantic → timeline)
  explain   Resolve a file or node and surface its checkpoint trail

Build is explicit; the pipeline does not run on hooks. Provider-backed
semantic synthesis reuses the summary-generation path; if no provider is
available the build still writes structural and history artifacts.`,
		PersistentPreRunE: func(cmd *cobra.Command, _ []string) error {
			if _, err := paths.WorktreeRoot(cmd.Context()); err != nil {
				return errors.New("not a git repository")
			}
			return nil
		},
	}

	cmd.AddCommand(newUnderstandStatusCmd())

	return cmd
}

package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/understand/graph"
	"github.com/spf13/cobra"
)

// newUnderstandStatusCmd builds `entire understand status`.
//
// Reports whether the cache exists, when it was built, and which provider/model
// was used for the semantic stage. Always exits 0 when the command can resolve
// the repo root — "no cache yet" is a normal status, not an error.
func newUnderstandStatusCmd() *cobra.Command {
	var jsonOut bool

	cmd := &cobra.Command{
		Use:   "status",
		Short: "Show understand build state and freshness",
		Long: `Report the state of the local understand cache.

Without --json, prints a human-readable summary.
With --json, emits the manifest plus a "present" boolean for scripting.`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runUnderstandStatus(cmd.Context(), cmd.OutOrStdout(), jsonOut)
		},
	}
	cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit JSON instead of text")
	return cmd
}

// statusReport is the JSON shape emitted by `status --json`.
type statusReport struct {
	Present  bool             `json:"present"`
	Manifest *graph.Manifest  `json:"manifest,omitempty"`
	Reason   string           `json:"reason,omitempty"`
	CacheDir string           `json:"cache_dir"`
}

func runUnderstandStatus(ctx context.Context, w io.Writer, jsonOut bool) error {
	root, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return err
	}
	store := graph.NewStore(root)

	report := statusReport{CacheDir: store.Root()}
	if !store.Exists() {
		report.Present = false
		report.Reason = "no understand cache yet — run `entire understand build`"
		return emitStatus(w, report, jsonOut)
	}

	manifest, err := store.ReadManifest()
	if err != nil {
		// A cache exists but its manifest is unreadable — surface this rather
		// than silently treating it as "no cache".
		if errors.Is(err, os.ErrNotExist) {
			report.Present = false
			report.Reason = "cache directory exists but manifest is missing"
			return emitStatus(w, report, jsonOut)
		}
		return fmt.Errorf("read manifest: %w", err)
	}

	report.Present = true
	report.Manifest = manifest
	return emitStatus(w, report, jsonOut)
}

func emitStatus(w io.Writer, r statusReport, jsonOut bool) error {
	if jsonOut {
		data, err := jsonutil.MarshalIndentWithNewline(r, "", "  ")
		if err != nil {
			return fmt.Errorf("marshal status: %w", err)
		}
		_, err = w.Write(data)
		return err
	}

	if !r.Present {
		fmt.Fprintf(w, "understand cache: not present\n")
		fmt.Fprintf(w, "  cache_dir: %s\n", r.CacheDir)
		if r.Reason != "" {
			fmt.Fprintf(w, "  reason: %s\n", r.Reason)
		}
		return nil
	}

	m := r.Manifest
	fmt.Fprintf(w, "understand cache: present\n")
	fmt.Fprintf(w, "  cache_dir: %s\n", r.CacheDir)
	fmt.Fprintf(w, "  schema_version: %d\n", m.SchemaVersion)
	fmt.Fprintf(w, "  build_id: %s\n", m.BuildID)
	if !m.BuiltAt.IsZero() {
		fmt.Fprintf(w, "  built_at: %s\n", m.BuiltAt.UTC().Format(time.RFC3339))
	}
	if m.RepoFingerprint != "" {
		fmt.Fprintf(w, "  repo_fingerprint: %s\n", m.RepoFingerprint)
	}
	if m.CheckpointHead != "" {
		fmt.Fprintf(w, "  checkpoint_head: %s\n", m.CheckpointHead)
	}
	fmt.Fprintf(w, "  structural: %s\n", orDash(m.StructuralStatus))
	fmt.Fprintf(w, "  history: %s\n", orDash(m.HistoryStatus))
	fmt.Fprintf(w, "  semantic: %s", orDash(string(m.SemanticStatus)))
	if m.SemanticProvider != "" {
		fmt.Fprintf(w, " (provider=%s", m.SemanticProvider)
		if m.SemanticModel != "" {
			fmt.Fprintf(w, ", model=%s", m.SemanticModel)
		}
		fmt.Fprintf(w, ")")
	}
	fmt.Fprintln(w)
	if m.SemanticReason != "" {
		fmt.Fprintf(w, "    reason: %s\n", m.SemanticReason)
	}
	if m.NodeCount > 0 || m.EdgeCount > 0 {
		fmt.Fprintf(w, "  graph: %d nodes, %d edges\n", m.NodeCount, m.EdgeCount)
	}
	return nil
}

func orDash(s string) string {
	if s == "" {
		return "-"
	}
	return s
}

package cli

import (
	"bytes"
	"context"
	"encoding/json"
	"strings"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/testutil"
	"github.com/entireio/cli/cmd/entire/cli/understand/graph"
)

func TestUnderstandStatus_NoCache_Text(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	t.Chdir(dir)
	paths.ClearWorktreeRootCache()

	var buf bytes.Buffer
	if err := runUnderstandStatus(context.Background(), &buf, false); err != nil {
		t.Fatalf("runUnderstandStatus: %v", err)
	}

	out := buf.String()
	if !strings.Contains(out, "not present") {
		t.Errorf("expected 'not present' in output; got:\n%s", out)
	}
	if !strings.Contains(out, "entire understand build") {
		t.Errorf("expected hint to run build in output; got:\n%s", out)
	}
}

func TestUnderstandStatus_NoCache_JSON(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	t.Chdir(dir)
	paths.ClearWorktreeRootCache()

	var buf bytes.Buffer
	if err := runUnderstandStatus(context.Background(), &buf, true); err != nil {
		t.Fatalf("runUnderstandStatus: %v", err)
	}

	var got statusReport
	if err := json.Unmarshal(buf.Bytes(), &got); err != nil {
		t.Fatalf("decode JSON: %v\nraw=%q", err, buf.String())
	}
	if got.Present {
		t.Errorf("Present = true; want false")
	}
	if got.Manifest != nil {
		t.Errorf("Manifest = %+v; want nil", got.Manifest)
	}
	if got.CacheDir == "" {
		t.Errorf("CacheDir empty; want a path")
	}
}

func TestUnderstandStatus_PresentCache_JSON(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	t.Chdir(dir)
	paths.ClearWorktreeRootCache()

	// Seed a manifest as if `build` had already run.
	store := graph.NewStore(dir)
	if err := store.WriteManifest(&graph.Manifest{
		BuildID:            "test-build-1",
		BuiltAt:            time.Date(2026, 5, 5, 12, 0, 0, 0, time.UTC),
		RepoFingerprint:    "abc123",
		StructuralStatus:   "ok",
		HistoryStatus:      "ok",
		SemanticStatus:     graph.SemanticSkipped,
		SemanticReason:     "no provider available",
		SupportedLanguages: []string{"go"},
		NodeCount:          7,
		EdgeCount:          11,
	}); err != nil {
		t.Fatalf("WriteManifest: %v", err)
	}

	var buf bytes.Buffer
	if err := runUnderstandStatus(context.Background(), &buf, true); err != nil {
		t.Fatalf("runUnderstandStatus: %v", err)
	}

	var got statusReport
	if err := json.Unmarshal(buf.Bytes(), &got); err != nil {
		t.Fatalf("decode JSON: %v\nraw=%q", err, buf.String())
	}
	if !got.Present {
		t.Fatalf("Present = false; want true")
	}
	if got.Manifest == nil {
		t.Fatalf("Manifest = nil; want present")
	}
	if got.Manifest.BuildID != "test-build-1" {
		t.Errorf("BuildID = %q; want test-build-1", got.Manifest.BuildID)
	}
	if got.Manifest.SemanticStatus != graph.SemanticSkipped {
		t.Errorf("SemanticStatus = %q; want %q", got.Manifest.SemanticStatus, graph.SemanticSkipped)
	}
	if got.Manifest.NodeCount != 7 {
		t.Errorf("NodeCount = %d; want 7", got.Manifest.NodeCount)
	}
}

func TestUnderstandStatus_PresentCache_Text(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	t.Chdir(dir)
	paths.ClearWorktreeRootCache()

	store := graph.NewStore(dir)
	if err := store.WriteManifest(&graph.Manifest{
		BuildID:          "build-2",
		BuiltAt:          time.Date(2026, 5, 5, 12, 0, 0, 0, time.UTC),
		StructuralStatus: "ok",
		HistoryStatus:    "ok",
		SemanticStatus:   graph.SemanticOK,
		SemanticProvider: "claude-code",
		SemanticModel:    "haiku",
		NodeCount:        50,
		EdgeCount:        40,
	}); err != nil {
		t.Fatalf("WriteManifest: %v", err)
	}

	var buf bytes.Buffer
	if err := runUnderstandStatus(context.Background(), &buf, false); err != nil {
		t.Fatalf("runUnderstandStatus: %v", err)
	}
	out := buf.String()
	for _, want := range []string{"present", "build-2", "structural: ok", "semantic: ok", "claude-code", "haiku", "50 nodes", "40 edges"} {
		if !strings.Contains(out, want) {
			t.Errorf("expected %q in output; got:\n%s", want, out)
		}
	}
}

