// GraphSlice is a minimal serializable form for the structural / history /
// semantic / timeline files. Each layer writes its own slice; readers fuse
// them at query time.
type GraphSlice struct {
	Nodes []Node `json:"nodes"`
	Edges []Edge `json:"edges"`
}

// WriteStructural persists the deterministic structural slice.
func (s *Store) WriteStructural(slice *GraphSlice) error {
	return s.writeJSON(structuralFile, sliceOrEmpty(slice))
}

// ReadStructural loads the structural slice. Returns an empty slice when the
// file is missing — callers can treat absence as "build hasn't run yet".
func (s *Store) ReadStructural() (*GraphSlice, error) {
	return s.readSlice(structuralFile)
}

// WriteHistory persists the history fusion slice.
func (s *Store) WriteHistory(slice *GraphSlice) error {
	return s.writeJSON(historyFile, sliceOrEmpty(slice))
}

// ReadHistory loads the history slice. Missing file → empty slice.
func (s *Store) ReadHistory() (*GraphSlice, error) {
	return s.readSlice(historyFile)
}

