// Package history fuses committed checkpoint metadata into the understand
// graph as first-class nodes plus `touched_in` / `belongs_to` edges.
//
// Per the spec checkpoints are nodes, not blob attributes. Symbol-level
// attribution requires deterministic evidence (diff hunk overlap, tool
// telemetry) — which we don't have at this layer — so all checkpoint→file
// edges are emitted with Scope=ScopeFileOwner. Future work can layer
// ScopeSymbol edges on top using diff parsers.
package history

import (
	"context"
	"errors"
	"fmt"
	"sort"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/understand/graph"
)

// FuseOptions configures how Fuse links checkpoints to structural nodes.
type FuseOptions struct {
	// StructuralFiles is the set of repo-relative file paths that exist in
	// the structural slice. Touched files outside this set become "ghost"
	// references — we still emit the edge but point at a synthetic
	// removed-file node so consumers can see that the file existed at
	// some point.
	StructuralFiles map[string]struct{}
}

// FuseResult is the outcome of a fusion pass.
type FuseResult struct {
	Slice           *graph.Slice
	CheckpointCount int
	SessionCount    int
	GhostFileCount  int
}

// Fuse turns a list of CommittedInfo into a graph slice. It is pure: no I/O.
// Callers are responsible for loading the CommittedInfo list (see LoadCommitted
// in this package) and for passing the structural file set.
func Fuse(infos []checkpoint.CommittedInfo, opts FuseOptions) (*FuseResult, error) {
	if opts.StructuralFiles == nil {
		opts.StructuralFiles = map[string]struct{}{}
	}

	slice := &graph.Slice{}
	seenSessions := map[string]struct{}{}
	seenGhostFiles := map[string]struct{}{}

	// Sort checkpoints by CreatedAt ascending for deterministic edge ordering.
	sorted := make([]checkpoint.CommittedInfo, len(infos))
	copy(sorted, infos)
	sort.Slice(sorted, func(i, j int) bool {
		if !sorted[i].CreatedAt.Equal(sorted[j].CreatedAt) {
			return sorted[i].CreatedAt.Before(sorted[j].CreatedAt)
		}
		return sorted[i].CheckpointID.String() < sorted[j].CheckpointID.String()
	})

	for _, info := range sorted {
		cpID := info.CheckpointID.String()
		if cpID == "" {
			continue
		}
		cpNodeID := "cp:" + cpID
		cpAttrs := map[string]any{
			"created_at":        info.CreatedAt.UTC().Format(time.RFC3339),
			"checkpoints_count": info.CheckpointsCount,
			"session_count":     info.SessionCount,
		}
		if info.Agent != "" {
			cpAttrs["agent"] = string(info.Agent)
		}
		if info.IsTask {
			cpAttrs["is_task"] = true
		}
		if info.ToolUseID != "" {
			cpAttrs["tool_use_id"] = info.ToolUseID
		}

		slice.Nodes = append(slice.Nodes, graph.Node{
			ID:    cpNodeID,
			Type:  graph.NodeCheckpoint,
			Name:  cpID,
			Attrs: cpAttrs,
		})

		// Sessions — emit each unique session id and link checkpoint → session.
		sessionIDs := info.SessionIDs
		if len(sessionIDs) == 0 && info.SessionID != "" {
			sessionIDs = []string{info.SessionID}
		}
		for _, sid := range sessionIDs {
			if sid == "" {
				continue
			}
			sessNodeID := "sess:" + sid
			if _, dup := seenSessions[sid]; !dup {
				slice.Nodes = append(slice.Nodes, graph.Node{
					ID:   sessNodeID,
					Type: graph.NodeSession,
					Name: sid,
				})
				seenSessions[sid] = struct{}{}
			}
			slice.Edges = append(slice.Edges, graph.Edge{
				ID:   "e:cp-belongs-sess:" + cpNodeID + "->" + sessNodeID,
				From: cpNodeID,
				To:   sessNodeID,
				Type: graph.EdgeBelongsTo,
			})
		}

		// File touches — Scope=ScopeFileOwner because we have no symbol-level
		// evidence at this layer.
		for _, raw := range info.FilesTouched {
			path := normalizeRel(raw)
			if path == "" {
				continue
			}
			fileID := "file:" + path
			if _, ok := opts.StructuralFiles[path]; !ok {
				// Ghost: file is referenced but no longer in the structural
				// slice. Emit a synthetic node once so dashboard/CLI can show
				// the touch without claiming the file exists.
				if _, dup := seenGhostFiles[path]; !dup {
					slice.Nodes = append(slice.Nodes, graph.Node{
						ID:    "ghost:" + path,
						Type:  graph.NodeFile,
						Name:  baseName(path),
						Path:  path,
						Attrs: map[string]any{"removed": true},
					})
					seenGhostFiles[path] = struct{}{}
				}
				fileID = "ghost:" + path
			}
			slice.Edges = append(slice.Edges, graph.Edge{
				ID:    "e:touched:" + cpNodeID + "->" + fileID,
				From:  cpNodeID,
				To:    fileID,
				Type:  graph.EdgeTouchedIn,
				Scope: graph.ScopeFileOwner,
			})
		}
	}

	return &FuseResult{
		Slice:           slice,
		CheckpointCount: len(sorted),
		SessionCount:    len(seenSessions),
		GhostFileCount:  len(seenGhostFiles),
	}, nil
}

// LoadCommitted reads committed checkpoints via the v1 store wrapper.
//
// This is a thin convenience over checkpoint.GitStore.ListCommitted; the build
// pipeline calls it once per build. It does not configure remote blob fetching
// — understand should work from local repo state per the spec ("no remote
// service dependency for core queries").
func LoadCommitted(ctx context.Context, store *checkpoint.GitStore) ([]checkpoint.CommittedInfo, error) {
	if store == nil {
		return nil, errors.New("history.LoadCommitted: nil store")
	}
	infos, err := store.ListCommitted(ctx)
	if err != nil {
		return nil, fmt.Errorf("list committed checkpoints: %w", err)
	}
	return infos, nil
}

func normalizeRel(p string) string {
	p = strings.TrimSpace(p)
	p = strings.ReplaceAll(p, "\\", "/")
	p = strings.TrimPrefix(p, "./")
	return p
}

func baseName(p string) string {
	if i := strings.LastIndex(p, "/"); i >= 0 {
		return p[i+1:]
	}
	return p
}

