package history

import (
	"slices"
	"testing"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent/types"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/understand/graph"
)

func mustID(s string) id.CheckpointID {
	cp, err := id.NewCheckpointID(s)
	if err != nil {
		panic(err)
	}
	return cp
}

func TestFuse_BasicCheckpointAndSessionNodes(t *testing.T) {
	t.Parallel()

	infos := []checkpoint.CommittedInfo{
		{
			CheckpointID:     mustID("a1b2c3d4e5f6"),
			SessionID:        "sess-1",
			CreatedAt:        time.Date(2026, 1, 1, 10, 0, 0, 0, time.UTC),
			CheckpointsCount: 1,
			SessionCount:     1,
			SessionIDs:       []string{"sess-1"},
			FilesTouched:     []string{"main.go", "lib/util.go"},
			Agent:            types.AgentType("claude-code"),
		},
	}

	res, err := Fuse(infos, FuseOptions{
		StructuralFiles: map[string]struct{}{"main.go": {}, "lib/util.go": {}},
	})
	if err != nil {
		t.Fatalf("Fuse: %v", err)
	}

	wantNodes := []string{"cp:a1b2c3d4e5f6", "sess:sess-1"}
	for _, want := range wantNodes {
		if !hasNode(res.Slice, want) {
			t.Errorf("missing node %q", want)
		}
	}

	for _, want := range []struct{ from, to, typ string }{
		{"cp:a1b2c3d4e5f6", "sess:sess-1", string(graph.EdgeBelongsTo)},
		{"cp:a1b2c3d4e5f6", "file:main.go", string(graph.EdgeTouchedIn)},
		{"cp:a1b2c3d4e5f6", "file:lib/util.go", string(graph.EdgeTouchedIn)},
	} {
		if !hasEdge(res.Slice, want.from, want.to, want.typ) {
			t.Errorf("missing edge %s -%s-> %s", want.from, want.typ, want.to)
		}
	}

	// Touched edges must be ScopeFileOwner per spec.
	for _, e := range res.Slice.Edges {
		if e.Type == graph.EdgeTouchedIn && e.Scope != graph.ScopeFileOwner {
			t.Errorf("touched_in edge %+v has Scope=%q; want %q", e, e.Scope, graph.ScopeFileOwner)
		}
	}

	if res.CheckpointCount != 1 || res.SessionCount != 1 || res.GhostFileCount != 0 {
		t.Errorf("counts = %+v; want CheckpointCount=1 SessionCount=1 GhostFileCount=0", res)
	}
}

func TestFuse_SessionDeduplicatedAcrossCheckpoints(t *testing.T) {
	t.Parallel()

	infos := []checkpoint.CommittedInfo{
		{
			CheckpointID: mustID("aaaaaaaaaaaa"),
			CreatedAt:    time.Date(2026, 1, 1, 10, 0, 0, 0, time.UTC),
			SessionIDs:   []string{"sess-1"},
		},
		{
			CheckpointID: mustID("bbbbbbbbbbbb"),
			CreatedAt:    time.Date(2026, 1, 2, 10, 0, 0, 0, time.UTC),
			SessionIDs:   []string{"sess-1"}, // same session, second checkpoint
		},
		{
			CheckpointID: mustID("cccccccccccc"),
			CreatedAt:    time.Date(2026, 1, 3, 10, 0, 0, 0, time.UTC),
			SessionIDs:   []string{"sess-2"},
		},
	}
	res, err := Fuse(infos, FuseOptions{})
	if err != nil {
		t.Fatalf("Fuse: %v", err)
	}

	sessionNodeIDs := []string{}
	for _, n := range res.Slice.Nodes {
		if n.Type == graph.NodeSession {
			sessionNodeIDs = append(sessionNodeIDs, n.ID)
		}
	}
	slices.Sort(sessionNodeIDs)
	want := []string{"sess:sess-1", "sess:sess-2"}
	if !slices.Equal(sessionNodeIDs, want) {
		t.Errorf("session nodes = %v; want %v", sessionNodeIDs, want)
	}
	if res.SessionCount != 2 {
		t.Errorf("SessionCount = %d; want 2", res.SessionCount)
	}
}

func TestFuse_GhostFileForRemovedPaths(t *testing.T) {
	t.Parallel()

	infos := []checkpoint.CommittedInfo{
		{
			CheckpointID: mustID("aaaaaaaaaaaa"),
			CreatedAt:    time.Now(),
			FilesTouched: []string{"current.go", "deleted.go"},
		},
	}
	res, err := Fuse(infos, FuseOptions{
		StructuralFiles: map[string]struct{}{"current.go": {}}, // deleted.go missing
	})
	if err != nil {
		t.Fatalf("Fuse: %v", err)
	}

	if !hasEdge(res.Slice, "cp:aaaaaaaaaaaa", "file:current.go", string(graph.EdgeTouchedIn)) {
		t.Error("missing live touched_in edge")
	}
	if !hasEdge(res.Slice, "cp:aaaaaaaaaaaa", "ghost:deleted.go", string(graph.EdgeTouchedIn)) {
		t.Error("missing ghost touched_in edge")
	}
	// Ghost node exists with `removed: true`.
	var ghost *graph.Node
	for i, n := range res.Slice.Nodes {
		if n.ID == "ghost:deleted.go" {
			ghost = &res.Slice.Nodes[i]
		}
	}
	if ghost == nil {
		t.Fatal("ghost node missing")
	}
	if ghost.Path != "deleted.go" {
		t.Errorf("ghost Path = %q; want deleted.go", ghost.Path)
	}
	if removed, _ := ghost.Attrs["removed"].(bool); !removed {
		t.Errorf("ghost.Attrs[removed] = %v; want true", ghost.Attrs["removed"])
	}
	if res.GhostFileCount != 1 {
		t.Errorf("GhostFileCount = %d; want 1", res.GhostFileCount)
	}
}

func TestFuse_DeterministicEdgeOrderByTime(t *testing.T) {
	t.Parallel()

	// Insert checkpoints out of order — Fuse should sort them by CreatedAt.
	infos := []checkpoint.CommittedInfo{
		{CheckpointID: mustID("cccccccccccc"), CreatedAt: time.Date(2026, 1, 3, 0, 0, 0, 0, time.UTC), FilesTouched: []string{"a.go"}},
		{CheckpointID: mustID("aaaaaaaaaaaa"), CreatedAt: time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC), FilesTouched: []string{"a.go"}},
		{CheckpointID: mustID("bbbbbbbbbbbb"), CreatedAt: time.Date(2026, 1, 2, 0, 0, 0, 0, time.UTC), FilesTouched: []string{"a.go"}},
	}
	res, err := Fuse(infos, FuseOptions{StructuralFiles: map[string]struct{}{"a.go": {}}})
	if err != nil {
		t.Fatalf("Fuse: %v", err)
	}

	// Edges referencing file:a.go should appear in chronological cp order.
	var seenCps []string
	for _, e := range res.Slice.Edges {
		if e.Type == graph.EdgeTouchedIn && e.To == "file:a.go" {
			seenCps = append(seenCps, e.From)
		}
	}
	want := []string{"cp:aaaaaaaaaaaa", "cp:bbbbbbbbbbbb", "cp:cccccccccccc"}
	if !slices.Equal(seenCps, want) {
		t.Errorf("edge order by cp = %v; want %v", seenCps, want)
	}
}

func TestFuse_EmptyInput(t *testing.T) {
	t.Parallel()

	res, err := Fuse(nil, FuseOptions{})
	if err != nil {
		t.Fatalf("Fuse(nil): %v", err)
	}
	if len(res.Slice.Nodes) != 0 || len(res.Slice.Edges) != 0 {
		t.Errorf("nodes/edges = %d/%d; want 0/0", len(res.Slice.Nodes), len(res.Slice.Edges))
	}
}

func hasNode(s *graph.Slice, id string) bool {
	for _, n := range s.Nodes {
		if n.ID == id {
			return true
		}
	}
	return false
}

func hasEdge(s *graph.Slice, from, to, typ string) bool {
	for _, e := range s.Edges {
		if e.From == from && e.To == to && string(e.Type) == typ {
			return true
		}
	}
	return false
}

