39	func resolveCheckpointSummaryProvider(ctx context.Context, w io.Writer) (*checkpointSummaryProvider, error) {
40		s, err := loadSummarySettings(ctx)
41		if err != nil {
42			return nil, fmt.Errorf("loading settings: %w", err)
43		}
44	
45		if s.SummaryGeneration != nil && s.SummaryGeneration.Provider != "" {
46			providerName := types.AgentName(s.SummaryGeneration.Provider)
47			discoverSummaryProviderIfMissing(ctx, providerName)
48			if err := ensureSummaryProviderPresent(ctx, providerName); err != nil {
49				return nil, err
50			}
51			return buildCheckpointSummaryProvider(providerName, s.SummaryGeneration.Model)
52		}
53	
54		// Use the always-variant so installed external plugins surface in the
55		// picker even when external_agents is currently off. Installation
56		// (placing entire-agent-* on $PATH) is the user's opt-in to "this
57		// plugin exists"; selecting it in the picker is when external_agents
58		// flips on (handled by persistSummaryProviderSelection).
59		discoverSummaryProvidersAlways(ctx)
60		candidates := listEnabledSummaryProviders(ctx)
61	
62		switch len(candidates) {
63		case 0:
64			return nil, errors.New("no summary-capable provider is available; install claude, codex, gemini, cursor, or copilot, install an external entire-agent-* plugin that declares text_generator, or set summary_generation.provider in settings")
65		case 1:
66			return autoSelectSummaryProvider(ctx, w, candidates[0].Name, "non-interactive auto-select: single installed provider")
67		default:
68			if !interactive.CanPromptInteractively() {
69				return autoSelectSummaryProvider(ctx, w, candidates[0].Name, "non-interactive auto-select: first detected of multiple")
70			}
71	
72			selected, err := promptForSummaryProvider(candidates)
73			if err != nil {
74				return nil, err
75			}
76			provider, err := autoSelectSummaryProvider(ctx, w, selected, "interactive prompt selection")
77			if err != nil {
78				return nil, err
79			}
80			fmt.Fprintf(w, "Using %s for summary generation.\n", provider.DisplayName)
81			return provider, nil
82		}
83	}
