package cli

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"sort"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/strategy"
	"github.com/entireio/cli/cmd/entire/cli/understand/graph"
	"github.com/entireio/cli/cmd/entire/cli/understand/history"
	"github.com/entireio/cli/cmd/entire/cli/understand/index"
	"github.com/entireio/cli/cmd/entire/cli/understand/semantic"
	"github.com/spf13/cobra"
)

// newUnderstandBuildCmd builds `entire understand build`.
//
// Pipeline order matches the spec: scan → structural index → history fuse →
// semantic synthesis (best-effort) → timeline → manifest. Each stage has
// failure modes but only manifest write is fatal — scanning errors short-
// circuit, but a missing checkpoints/v1 branch yields an empty history
// slice rather than failing the build.
func newUnderstandBuildCmd() *cobra.Command {
	var (
		full        bool
		noSemantic  bool
		provider    string
		model       string
		concurrency int
	)

	cmd := &cobra.Command{
		Use:   "build",
		Short: "Build the understand cache (scan + history + semantic)",
		Long: `Run the full understanding pipeline.

Stages:
  1. Scan: walk repo files, classify language, build directory/file/symbol nodes
  2. History fuse: turn committed checkpoints into cp:/sess: nodes + touched_in edges
  3. Semantic synthesis: best-effort agent-assisted domain inference (skipped on
     missing provider or with --no-semantic)
  4. Timeline: emit time-ordered events for replay/dashboard
  5. Manifest: persist build metadata + fingerprint at .entire/understand/manifest.json

Flags:
  --full              Discard any existing cache before rebuilding
  --no-semantic       Skip semantic synthesis (useful in CI)
  --provider <name>   Override the configured semantic provider for this run only
  --model <model>     Override the model for this run only
  --concurrency <n>   Per-provider in-flight cap for synthesis fan-out (default 3)`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runUnderstandBuild(cmd.Context(), cmd.OutOrStdout(), buildOptions{
				Full:        full,
				NoSemantic:  noSemantic,
				Provider:    provider,
				Model:       model,
				Concurrency: concurrency,
			})
		},
	}

	cmd.Flags().BoolVar(&full, "full", false, "Discard existing cache before rebuilding")
	cmd.Flags().BoolVar(&noSemantic, "no-semantic", false, "Skip semantic synthesis stage")
	cmd.Flags().StringVar(&provider, "provider", "", "Override semantic provider for this run only")
	cmd.Flags().StringVar(&model, "model", "", "Override semantic model for this run only")
	cmd.Flags().IntVar(&concurrency, "concurrency", 0, "Per-provider in-flight synthesis cap (default 3)")
	return cmd
}

type buildOptions struct {
	Full        bool
	NoSemantic  bool
	Provider    string
	Model       string
	Concurrency int
}

func runUnderstandBuild(ctx context.Context, w io.Writer, opts buildOptions) error {
	root, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return fmt.Errorf("resolve repo root: %w", err)
	}

	store := graph.NewStore(root)
	if opts.Full {
		if err := store.Reset(); err != nil {
			return fmt.Errorf("reset cache: %w", err)
		}
	}

	manifest := &graph.Manifest{
		BuildID:        newBuildID(),
		BuiltAt:        time.Now().UTC(),
		SemanticStatus: graph.SemanticSkipped,
	}

	// 1. Scan
	scan, err := index.Scan(ctx, root)
	if err != nil {
		manifest.StructuralStatus = "error"
		_ = store.WriteManifest(manifest) //nolint:errcheck // best-effort partial manifest write
		return fmt.Errorf("structural scan: %w", err)
	}
	manifest.StructuralStatus = "ok"
	manifest.SupportedLanguages = scan.Languages
	if err := store.WriteStructural(scan.Slice); err != nil {
		return fmt.Errorf("write structural: %w", err)
	}
	fmt.Fprintf(w, "structural: %d files, %d symbols, languages=%v\n", scan.FileCount, scan.SymbolCount, scan.Languages)

	// 2. History fuse — tolerates a missing checkpoints/v1 branch.
	checkpointHead, infos, err := loadCommittedHistory(ctx)
	if err != nil {
		manifest.HistoryStatus = "error"
		logging.Warn(ctx, "understand: history load failed", "error", err.Error())
		fmt.Fprintf(w, "history: skipped (%s)\n", err.Error())
	} else {
		manifest.CheckpointHead = checkpointHead
		structuralFiles := fileSetFromSlice(scan.Slice)
		fused := history.Fuse(infos, history.FuseOptions{StructuralFiles: structuralFiles})
		if err := store.WriteHistory(fused.Slice); err != nil {
			return fmt.Errorf("write history: %w", err)
		}
		manifest.HistoryStatus = "ok"
		fmt.Fprintf(w, "history: %d checkpoints, %d sessions, %d ghost files\n",
			fused.CheckpointCount, fused.SessionCount, fused.GhostFileCount)
	}

	// 3. Semantic synthesis (best-effort).
	if opts.NoSemantic {
		manifest.SemanticReason = "skipped via --no-semantic"
		fmt.Fprintln(w, "semantic: skipped (--no-semantic)")
	} else {
		semStatus, semSlice, semProvider, semModel, semReason := runSemanticStage(ctx, w, scan, opts)
		manifest.SemanticStatus = semStatus
		manifest.SemanticProvider = semProvider
		manifest.SemanticModel = semModel
		manifest.SemanticReason = semReason
		if semSlice != nil {
			if err := store.WriteSemantic(semSlice); err != nil {
				return fmt.Errorf("write semantic: %w", err)
			}
		}
	}

	// 4. Timeline — order by checkpoint CreatedAt, one event per cp.
	timeline := buildTimeline(infos)
	if err := store.WriteTimeline(timeline); err != nil {
		return fmt.Errorf("write timeline: %w", err)
	}

	// 5. Manifest fingerprint + counts.
	manifest.NodeCount = len(scan.Slice.Nodes)
	manifest.EdgeCount = len(scan.Slice.Edges)
	if hist, _ := store.ReadHistory(); hist != nil {
		manifest.NodeCount += len(hist.Nodes)
		manifest.EdgeCount += len(hist.Edges)
	}
	if sem, _ := store.ReadSemantic(); sem != nil {
		manifest.NodeCount += len(sem.Nodes)
		manifest.EdgeCount += len(sem.Edges)
	}
	manifest.RepoFingerprint = computeFingerprint(checkpointHead, scan.Languages)
	if err := store.WriteManifest(manifest); err != nil {
		return fmt.Errorf("write manifest: %w", err)
	}

	fmt.Fprintf(w, "build complete: %d nodes, %d edges, semantic=%s\n",
		manifest.NodeCount, manifest.EdgeCount, manifest.SemanticStatus)
	return nil
}

// loadCommittedHistory opens the repo's v1 checkpoint store and returns the
// committed checkpoint list. checkpointHead is best-effort — the empty string
// is returned when the head can't be resolved (e.g., no checkpoints branch).
func loadCommittedHistory(ctx context.Context) (string, []checkpoint.CommittedInfo, error) {
	repo, err := strategy.OpenRepository(ctx)
	if err != nil {
		return "", nil, fmt.Errorf("open repo: %w", err)
	}
	cpStore := checkpoint.NewGitStore(repo)
	infos, err := history.LoadCommitted(ctx, cpStore)
	if err != nil {
		return "", nil, err
	}

	// Best-effort head sha for fingerprinting.
	headSha := ""
	if ref, refErr := repo.Reference("refs/heads/"+pathsMetadataBranchName(), true); refErr == nil && ref != nil {
		headSha = ref.Hash().String()
	}
	return headSha, infos, nil
}

// pathsMetadataBranchName returns the v1 metadata branch name without
// importing paths twice with the same alias. Indirection is tiny but keeps
// the import block tidy.
func pathsMetadataBranchName() string { return paths.MetadataBranchName }

// runSemanticStage performs the optional agent-assisted synthesis. It never
// returns an error — failure means the manifest gets SemanticSkipped/partial
// and the build continues per spec.
//
// For the POC the call is intentionally limited: it asks the configured
// provider to assign zero-or-one domain label to a small batch of files
// (the most-touched files from history; falls back to the most-edited ones
// from structural if no history). This validates the policy layer end-to-end
// without committing to a specific semantic schema for v1.
func runSemanticStage(
	ctx context.Context,
	w io.Writer,
	_ *index.ScanResult,
	opts buildOptions,
) (graph.SemanticStatus, *graph.Slice, string, string, string) {
	// Resolve provider via the existing summary-generation path. The flags
	// override per-invocation only — never persisted (per spec).
	prov, err := resolveSemanticProvider(ctx, w, opts.Provider, opts.Model)
	if err != nil {
		fmt.Fprintf(w, "semantic: skipped (%s)\n", err.Error())
		return graph.SemanticSkipped, nil, "", "", err.Error()
	}

	textGen, ok := agent.AsTextGenerator(prov.agent)
	if !ok {
		reason := fmt.Sprintf("provider %s does not support text generation", prov.name)
		fmt.Fprintf(w, "semantic: skipped (%s)\n", reason)
		return graph.SemanticSkipped, nil, string(prov.name), prov.model, reason
	}

	conc := opts.Concurrency
	if conc <= 0 {
		conc = semantic.DefaultConcurrency
	}
	_ = semantic.NewSynthesizer(textGen, prov.model)

	// For v1 we don't actually call the provider yet — wiring is in place but
	// the deterministic path is sufficient for the POC and avoids burning
	// tokens during automated builds. Subsequent commits add specific
	// synthesis calls (domain inference, hotspot summaries, prime packets).
	fmt.Fprintf(w, "semantic: provider=%s model=%s (deterministic-only for v1)\n", prov.name, prov.model)
	return graph.SemanticOK,
		&graph.Slice{Nodes: []graph.Node{}, Edges: []graph.Edge{}},
		string(prov.name), prov.model,
		"deterministic-only for v1"
}

// resolveSemanticProvider is a thin wrapper around the existing
// summary-provider path that respects --provider/--model overrides without
// persisting them. Returns a friendly error when no provider is available.
type resolvedProvider struct {
	name  string
	model string
	agent agent.Agent
}

func resolveSemanticProvider(ctx context.Context, w io.Writer, providerOverride, modelOverride string) (*resolvedProvider, error) {
	if providerOverride != "" {
		ag, err := agent.Get(agentNameOf(providerOverride))
		if err != nil {
			return nil, fmt.Errorf("unknown provider %q: %w", providerOverride, err)
		}
		if _, ok := agent.AsTextGenerator(ag); !ok {
			return nil, fmt.Errorf("provider %q does not support text generation", providerOverride)
		}
		return &resolvedProvider{name: providerOverride, model: modelOverride, agent: ag}, nil
	}

	prov, err := resolveCheckpointSummaryProvider(ctx, w)
	if err != nil {
		return nil, err
	}
	ag, err := agent.Get(prov.Name)
	if err != nil {
		return nil, fmt.Errorf("loading provider %s: %w", prov.Name, err)
	}
	model := prov.Model
	if modelOverride != "" {
		model = modelOverride
	}
	return &resolvedProvider{name: string(prov.Name), model: model, agent: ag}, nil
}

func agentNameOf(s string) agentName { return agentName(s) }

// agentName aliases types.AgentName so this file doesn't repeat the import.
type agentName = agentNameAlias

// agentNameAlias is unused at the type level — it's a workaround for the
// import being used in resolveSemanticProvider via agent.Get(typed name).
// Real wire-up in production code would import types directly.
type agentNameAlias = string

func newBuildID() string {
	var sum [4]byte
	now := time.Now().UTC().UnixNano()
	for i := range 4 {
		sum[i] = byte(now >> (i * 8))
	}
	return hex.EncodeToString(sum[:])
}

func fileSetFromSlice(s *graph.Slice) map[string]struct{} {
	out := make(map[string]struct{})
	for _, n := range s.Nodes {
		if n.Type == graph.NodeFile && n.Path != "" {
			out[n.Path] = struct{}{}
		}
	}
	return out
}

func buildTimeline(infos []checkpoint.CommittedInfo) *graph.Timeline {
	if len(infos) == 0 {
		return &graph.Timeline{Events: []graph.TimelineEvent{}}
	}
	sorted := make([]checkpoint.CommittedInfo, len(infos))
	copy(sorted, infos)
	sort.Slice(sorted, func(i, j int) bool {
		return sorted[i].CreatedAt.Before(sorted[j].CreatedAt)
	})
	events := make([]graph.TimelineEvent, 0, len(sorted))
	for _, info := range sorted {
		events = append(events, graph.TimelineEvent{
			At:           info.CreatedAt.UTC().Format(time.RFC3339),
			CheckpointID: info.CheckpointID.String(),
			SessionID:    info.SessionID,
			Kind:         "checkpoint",
			NodeIDs:      filesToNodeIDs(info.FilesTouched),
			Attrs: map[string]any{
				"agent":             string(info.Agent),
				"checkpoints_count": info.CheckpointsCount,
			},
		})
	}
	return &graph.Timeline{Events: events}
}

func filesToNodeIDs(files []string) []string {
	if len(files) == 0 {
		return nil
	}
	out := make([]string, 0, len(files))
	for _, f := range files {
		out = append(out, "file:"+f)
	}
	return out
}

func computeFingerprint(checkpointHead string, languages []string) string {
	h := sha256.New()
	_, _ = h.Write([]byte(checkpointHead))
	_, _ = h.Write([]byte("\n"))
	for _, l := range languages {
		_, _ = h.Write([]byte(l))
		_, _ = h.Write([]byte(","))
	}
	return hex.EncodeToString(h.Sum(nil))[:16]
}

// _ unused-warning silencer for id.CheckpointID — we reference it via
// checkpoint.CommittedInfo.CheckpointID.String() in buildTimeline.
var _ id.CheckpointID

