func TestUnderstandBuild_NoSemantic_NoCheckpoints(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	testutil.WriteFile(t, dir, "main.go", "package main\nfunc main() {}\n")
	testutil.WriteFile(t, dir, "lib/util.go", "package lib\nfunc Hello() string { return \"hi\" }\n")
	testutil.GitAdd(t, dir, "main.go")
	testutil.GitCommit(t, dir, "init")
	t.Chdir(dir)
	paths.ClearWorktreeRootCache()

	var buf bytes.Buffer
	if err := runUnderstandBuild(context.Background(), &buf, buildOptions{NoSemantic: true}); err != nil {
		t.Fatalf("runUnderstandBuild: %v", err)
	}

	out := buf.String()
	if !strings.Contains(out, "structural:") {
		t.Errorf("missing structural progress line; got:\n%s", out)
	}
	if !strings.Contains(out, "semantic: skipped (--no-semantic)") {
		t.Errorf("missing --no-semantic skip line; got:\n%s", out)
	}
	if !strings.Contains(out, "build complete") {
		t.Errorf("missing completion line; got:\n%s", out)
	}

	// Manifest should now exist with structural=ok, semantic=skipped.
	store := graph.NewStore(dir)
	manifest, err := store.ReadManifest()
	if err != nil {
		t.Fatalf("ReadManifest: %v", err)
	}
	if manifest.StructuralStatus != "ok" {
		t.Errorf("StructuralStatus=%q; want ok", manifest.StructuralStatus)
	}
	if manifest.SemanticStatus != graph.SemanticSkipped {
		t.Errorf("SemanticStatus=%q; want skipped", manifest.SemanticStatus)
	}
	if manifest.NodeCount == 0 {
		t.Errorf("NodeCount=0; want >0 (we wrote two go files)")
	}
	if !contains(manifest.SupportedLanguages, "go") {
		t.Errorf("SupportedLanguages=%v; want to include go", manifest.SupportedLanguages)
	}

	// Structural slice must round-trip through the store.
	str, err := store.ReadStructural()
	if err != nil {
		t.Fatalf("ReadStructural: %v", err)
	}
	if len(str.Nodes) == 0 {
		t.Errorf("structural nodes empty after build")
	}

	// History slice exists but is empty (no checkpoints branch yet).
	hist, err := store.ReadHistory()
	if err != nil {
		t.Fatalf("ReadHistory: %v", err)
	}
	if len(hist.Nodes) != 0 {
		t.Errorf("history nodes=%d; want 0 (no checkpoints branch)", len(hist.Nodes))
	}

	// Timeline written, even if empty.
	tl, err := store.ReadTimeline()
	if err != nil {
		t.Fatalf("ReadTimeline: %v", err)
	}
	if tl.Events == nil {
		t.Errorf("Timeline.Events nil; want empty slice")
	}
}

func TestUnderstandBuild_FullResetsCache(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	testutil.WriteFile(t, dir, "main.go", "package main\nfunc main() {}\n")
	testutil.GitAdd(t, dir, "main.go")
	testutil.GitCommit(t, dir, "init")
	t.Chdir(dir)
	paths.ClearWorktreeRootCache()

	// Seed a stale manifest to confirm --full wipes it.
	store := graph.NewStore(dir)
	if err := store.WriteManifest(&graph.Manifest{BuildID: "stale", StructuralStatus: "stale"}); err != nil {
		t.Fatalf("seed stale manifest: %v", err)
	}

	var buf bytes.Buffer
	if err := runUnderstandBuild(context.Background(), &buf, buildOptions{NoSemantic: true, Full: true}); err != nil {
		t.Fatalf("runUnderstandBuild: %v", err)
	}
	manifest, err := store.ReadManifest()
	if err != nil {
		t.Fatalf("ReadManifest: %v", err)
	}
	if manifest.BuildID == "stale" {
		t.Errorf("BuildID still %q; --full should have produced a fresh build", manifest.BuildID)
	}
	if manifest.StructuralStatus != "ok" {
		t.Errorf("StructuralStatus=%q; want ok", manifest.StructuralStatus)
	}
}

func TestUnderstandBuild_FingerprintStable(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	testutil.WriteFile(t, dir, "main.go", "package main\nfunc main() {}\n")
	testutil.GitAdd(t, dir, "main.go")
	testutil.GitCommit(t, dir, "init")
	t.Chdir(dir)
	paths.ClearWorktreeRootCache()

	var buf bytes.Buffer
	if err := runUnderstandBuild(context.Background(), &buf, buildOptions{NoSemantic: true}); err != nil {
		t.Fatalf("first build: %v", err)
	}
	store := graph.NewStore(dir)
	first, err := store.ReadManifest()
	if err != nil {
		t.Fatalf("ReadManifest 1: %v", err)
	}

	buf.Reset()
	if err := runUnderstandBuild(context.Background(), &buf, buildOptions{NoSemantic: true}); err != nil {
		t.Fatalf("second build: %v", err)
	}
	second, err := store.ReadManifest()
	if err != nil {
		t.Fatalf("ReadManifest 2: %v", err)
	}

	if first.RepoFingerprint != second.RepoFingerprint {
		t.Errorf("fingerprint changed across no-op rebuilds: %q vs %q",
			first.RepoFingerprint, second.RepoFingerprint)
	}
}

func contains(haystack []string, needle string) bool {
	for _, h := range haystack {
		if h == needle {
			return true
		}
	}
	return false
}

