package cli

import (
	"context"
	"fmt"
	"sort"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/understand/graph"
)

// queryEnv is the read-side scaffolding shared by tour/impact/examples/hotspots.
// It loads the fused graph plus the manifest once per command invocation and
// exposes precomputed lookups (node-by-ID, contains-children, touched_in
// counts).
type queryEnv struct {
	root     string
	store    *graph.Store
	manifest *graph.Manifest
	fused    *graph.Slice

	byID         map[string]*graph.Node
	containsFrom map[string][]*graph.Node // parent -> direct children via EdgeContains
	touchedCount map[string]int           // file/ghost ID -> distinct cp count
	touchedCps   map[string][]string      // file/ghost ID -> cp node IDs (chronological)
}

// loadQueryEnv returns a fully-populated queryEnv. Returns a "no cache" sentinel
// error when the build hasn't run; commands surface that to the user with a
// hint to run build, then exit cleanly.
func loadQueryEnv(ctx context.Context) (*queryEnv, error) {
	root, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return nil, fmt.Errorf("resolve repo root: %w", err)
	}
	store := graph.NewStore(root)
	if !store.Exists() {
		return nil, errNoUnderstandCache
	}
	manifest, err := store.ReadManifest()
	if err != nil {
		return nil, fmt.Errorf("read manifest: %w", err)
	}
	fused, err := store.FusedGraph()
	if err != nil {
		return nil, fmt.Errorf("read fused graph: %w", err)
	}

	q := &queryEnv{
		root:         root,
		store:        store,
		manifest:     manifest,
		fused:        fused,
		byID:         make(map[string]*graph.Node, len(fused.Nodes)),
		containsFrom: make(map[string][]*graph.Node),
		touchedCount: map[string]int{},
		touchedCps:   map[string][]string{},
	}
	for i := range fused.Nodes {
		q.byID[fused.Nodes[i].ID] = &fused.Nodes[i]
	}
	for _, e := range fused.Edges {
		if e.Type == graph.EdgeContains {
			if child, ok := q.byID[e.To]; ok {
				q.containsFrom[e.From] = append(q.containsFrom[e.From], child)
			}
		}
		if e.Type == graph.EdgeTouchedIn {
			q.touchedCount[e.To]++
			q.touchedCps[e.To] = append(q.touchedCps[e.To], e.From)
		}
	}
	// Stable child ordering for tour/explain.
	for k := range q.containsFrom {
		children := q.containsFrom[k]
		sort.Slice(children, func(i, j int) bool { return children[i].ID < children[j].ID })
		q.containsFrom[k] = children
	}
	return q, nil
}

// errNoUnderstandCache is returned by loadQueryEnv when the build has not run.
// Commands check for this sentinel and emit a friendly hint rather than the
// generic error. Defined as a single package-level value so callers can use
// errors.Is.
var errNoUnderstandCache = noUnderstandCacheError{}

type noUnderstandCacheError struct{}

func (noUnderstandCacheError) Error() string {
	return "no understand cache yet — run `entire understand build`"
}

// descendantFiles walks contains-edges from start and returns every file or
// ghost node reachable. Order is preserved (BFS). Used by tour and impact to
// build subtree views without rewalking the graph each time.
func (q *queryEnv) descendantFiles(start string) []*graph.Node {
	out := []*graph.Node{}
	if start == "" {
		return out
	}
	seen := map[string]bool{start: true}
	queue := []string{start}
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		for _, child := range q.containsFrom[cur] {
			if seen[child.ID] {
				continue
			}
			seen[child.ID] = true
			if child.Type == graph.NodeFile {
				out = append(out, child)
			}
			queue = append(queue, child.ID)
		}
	}
	return out
}

// resolveAreaNode picks the right starting node for tour/impact. Resolution is
// the same as explain's resolver, defined separately so the helper file
// doesn't depend on understand_explain.go beyond what's already exported.
func (q *queryEnv) resolveAreaNode(target string) (*graph.Node, error) {
	return resolveExplainNode(q.fused, target, q.root)
}

// recentCheckpoint returns the highest-CreatedAt cp node among those touching
// `nodeID`, or nil when none exist. Useful for tour stop annotations.
func (q *queryEnv) recentCheckpoint(nodeID string) *graph.Node {
	cps := q.touchedCps[nodeID]
	if len(cps) == 0 {
		return nil
	}
	var best *graph.Node
	bestAt := ""
	for _, cpID := range cps {
		cp := q.byID[cpID]
		if cp == nil {
			continue
		}
		at, _ := cp.Attrs["created_at"].(string)
		if best == nil || at > bestAt {
			best = cp
			bestAt = at
		}
	}
	return best
}

package cli

import (
	"context"
	"errors"
	"fmt"
	"io"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/spf13/cobra"
)

// newUnderstandTourCmd builds `entire understand tour <area>`.
//
// Per the spec the tour is a guided walk through a structural neighborhood
// annotated with the checkpoints that most recently shaped each stop. For the
// POC we ship the deterministic stops + checkpoint annotations; semantic
// narration is gated behind the build pipeline (deterministic-only for v1).
func newUnderstandTourCmd() *cobra.Command {
	var jsonOut bool
	var maxStops int

	cmd := &cobra.Command{
		Use:   "tour <area>",
		Short: "Guided structural walk annotated with checkpoint history",
		Long: `Resolve <area> to a file/dir/module/node and walk its descendants. Each stop
includes the most recent touching checkpoint when available.

Examples:
  entire understand tour cmd/
  entire understand tour cmd/entire/cli/understand
  entire understand tour file:cmd/entire/cli/root.go`,
		Args: cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			return runUnderstandTour(cmd.Context(), cmd.OutOrStdout(), args[0], jsonOut, maxStops)
		},
	}
	cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit JSON instead of markdown")
	cmd.Flags().IntVar(&maxStops, "max-stops", 25, "Maximum number of stops to include")
	return cmd
}

type tourStop struct {
	NodeID         string `json:"node_id"`
	Name           string `json:"name"`
	Path           string `json:"path,omitempty"`
	Language       string `json:"language,omitempty"`
	LastCheckpoint string `json:"last_checkpoint,omitempty"`
	LastAt         string `json:"last_at,omitempty"`
	LastAgent      string `json:"last_agent,omitempty"`
}

type tourReport struct {
	Area    string     `json:"area"`
	NodeID  string     `json:"node_id"`
	Stops   []tourStop `json:"stops"`
	Skipped int        `json:"skipped,omitempty"`
}

func runUnderstandTour(ctx context.Context, w io.Writer, target string, jsonOut bool, maxStops int) error {
	q, err := loadQueryEnv(ctx)
	if err != nil {
		if errors.Is(err, errNoUnderstandCache) {
			fmt.Fprintln(w, err.Error())
			return nil
		}
		return err
	}
	node, err := q.resolveAreaNode(target)
	if err != nil {
		return err
	}

	files := q.descendantFiles(node.ID)
	report := tourReport{Area: target, NodeID: node.ID}
	if maxStops <= 0 {
		maxStops = 25
	}
	for i, f := range files {
		if i >= maxStops {
			report.Skipped = len(files) - i
			break
		}
		stop := tourStop{
			NodeID:   f.ID,
			Name:     f.Name,
			Path:     f.Path,
			Language: f.Language,
		}
		if cp := q.recentCheckpoint(f.ID); cp != nil {
			stop.LastCheckpoint = cp.Name
			if at, ok := cp.Attrs["created_at"].(string); ok {
				stop.LastAt = at
			}
			if ag, ok := cp.Attrs["agent"].(string); ok {
				stop.LastAgent = ag
			}
		}
		report.Stops = append(report.Stops, stop)
	}

	return emitTour(w, report, jsonOut)
}

func emitTour(w io.Writer, r tourReport, jsonOut bool) error {
	if jsonOut {
		data, err := jsonutil.MarshalIndentWithNewline(r, "", "  ")
		if err != nil {
			return fmt.Errorf("marshal tour: %w", err)
		}
		if _, err := w.Write(data); err != nil {
			return fmt.Errorf("write tour JSON: %w", err)
		}
		return nil
	}
	fmt.Fprintf(w, "# Tour: %s (`%s`)\n\n", r.Area, r.NodeID)
	if len(r.Stops) == 0 {
		fmt.Fprintln(w, "_No file descendants found at this area._")
		return nil
	}
	for i, s := range r.Stops {
		fmt.Fprintf(w, "%d. **%s**", i+1, s.Path)
		if s.Language != "" {
			fmt.Fprintf(w, " _(%s)_", s.Language)
		}
		fmt.Fprintln(w)
		if s.LastCheckpoint != "" {
			fmt.Fprintf(w, "   - last touched in `%s`", s.LastCheckpoint)
			if s.LastAt != "" {
				fmt.Fprintf(w, " at %s", s.LastAt)
			}
			if s.LastAgent != "" {
				fmt.Fprintf(w, " by %s", s.LastAgent)
			}
			fmt.Fprintln(w)
		} else {
			fmt.Fprintln(w, "   - no checkpoint trail yet")
		}
	}
	if r.Skipped > 0 {
		fmt.Fprintf(w, "\n_…%d more files omitted (raise --max-stops to see all)._\n", r.Skipped)
	}
	return nil
}

package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"sort"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/understand/graph"
	"github.com/spf13/cobra"
)

// newUnderstandImpactCmd builds `entire understand impact <file|node>`.
//
// For the POC the impact analysis is structural: starting from the resolved
// node, walk contains-edges to find sibling/descendant files plus
// touched_in-edges to find files that share a checkpoint history with the
// target. Each affected file is annotated with its last touching checkpoint.
//
// Symbol-level call/import edges are not yet emitted by the structural index
// (Go-only POC, no go/types resolution); when those land, this command will
// pick them up automatically because the walker is already shape-flexible.
func newUnderstandImpactCmd() *cobra.Command {
	var jsonOut bool
	var maxAffected int

	cmd := &cobra.Command{
		Use:   "impact <file|node>",
		Short: "Estimate the structural and historical blast radius of a change",
		Long: `Walk dependency and ownership edges from the target and rank affected nodes.
For the POC the relations considered are 'contains' (siblings/descendants) and
'touched_in' (files that share a checkpoint history with the target).

Examples:
  entire understand impact cmd/entire/cli/root.go
  entire understand impact dir:cmd/entire/cli/understand`,
		Args: cobra.ExactArgs(1),
		RunE: func(cmd *cobra.Command, args []string) error {
			return runUnderstandImpact(cmd.Context(), cmd.OutOrStdout(), args[0], jsonOut, maxAffected)
		},
	}
	cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit JSON instead of markdown")
	cmd.Flags().IntVar(&maxAffected, "max", 30, "Maximum number of affected nodes to list")
	return cmd
}

type impactNeighbor struct {
	NodeID         string `json:"node_id"`
	Path           string `json:"path,omitempty"`
	Type           string `json:"type"`
	Reason         string `json:"reason"`
	SharedCps      int    `json:"shared_checkpoints,omitempty"`
	LastCheckpoint string `json:"last_checkpoint,omitempty"`
	LastAt         string `json:"last_at,omitempty"`
}

type impactReport struct {
	Target    string           `json:"target"`
	NodeID    string           `json:"node_id"`
	Affected  []impactNeighbor `json:"affected"`
	Truncated bool             `json:"truncated,omitempty"`
}

func runUnderstandImpact(ctx context.Context, w io.Writer, target string, jsonOut bool, maxAffected int) error {
	q, err := loadQueryEnv(ctx)
	if err != nil {
		if errors.Is(err, errNoUnderstandCache) {
			fmt.Fprintln(w, err.Error())
			return nil
		}
		return err
	}
	node, err := q.resolveAreaNode(target)
	if err != nil {
		return err
	}

	report := impactReport{Target: target, NodeID: node.ID}

	// Collect "shared checkpoint" siblings: files that appear in the same
	// touched_in edge set as the target. Score by number of overlapping cps.
	shared := computeImpactSharedCheckpoints(q, node.ID)

	// Collect contains-descendants for area-style queries (dir:/repo:.).
	descendants := q.descendantFiles(node.ID)

	// Merge and de-dupe (descendants take precedence over shared, since their
	// reason is structural rather than inferred).
	seen := map[string]bool{node.ID: true}
	for _, d := range descendants {
		if seen[d.ID] {
			continue
		}
		seen[d.ID] = true
		report.Affected = append(report.Affected, neighborFor(q, d, "contains"))
	}
	// Sort shared by overlap desc, recency desc.
	type sharedEntry struct {
		nodeID  string
		count   int
		lastAt  string
	}
	entries := make([]sharedEntry, 0, len(shared))
	for id, count := range shared {
		if seen[id] {
			continue
		}
		var lastAt string
		if cp := q.recentCheckpoint(id); cp != nil {
			lastAt, _ = cp.Attrs["created_at"].(string)
		}
		entries = append(entries, sharedEntry{nodeID: id, count: count, lastAt: lastAt})
	}
	sort.Slice(entries, func(i, j int) bool {
		if entries[i].count != entries[j].count {
			return entries[i].count > entries[j].count
		}
		return entries[i].lastAt > entries[j].lastAt
	})
	for _, e := range entries {
		n := q.byID[e.nodeID]
		if n == nil {
			continue
		}
		nb := neighborFor(q, n, fmt.Sprintf("shares %d checkpoint(s)", e.count))
		nb.SharedCps = e.count
		report.Affected = append(report.Affected, nb)
	}

	if maxAffected > 0 && len(report.Affected) > maxAffected {
		report.Affected = report.Affected[:maxAffected]
		report.Truncated = true
	}

	return emitImpact(w, report, jsonOut)
}

// computeImpactSharedCheckpoints returns map[fileNodeID]sharedCpCount for files
// that share at least one cp with `targetID`.
func computeImpactSharedCheckpoints(q *queryEnv, targetID string) map[string]int {
	cpsForTarget := map[string]struct{}{}
	for _, cpID := range q.touchedCps[targetID] {
		cpsForTarget[cpID] = struct{}{}
	}
	if len(cpsForTarget) == 0 {
		return nil
	}
	out := map[string]int{}
	for fileID, cps := range q.touchedCps {
		if fileID == targetID {
			continue
		}
		count := 0
		for _, cp := range cps {
			if _, ok := cpsForTarget[cp]; ok {
				count++
			}
		}
		if count > 0 {
			out[fileID] = count
		}
	}
	return out
}

func neighborFor(q *queryEnv, n *graph.Node, reason string) impactNeighbor {
	nb := impactNeighbor{
		NodeID: n.ID,
		Path:   n.Path,
		Type:   string(n.Type),
		Reason: reason,
	}
	if cp := q.recentCheckpoint(n.ID); cp != nil {
		nb.LastCheckpoint = cp.Name
		if at, ok := cp.Attrs["created_at"].(string); ok {
			nb.LastAt = at
		}
	}
	return nb
}

func emitImpact(w io.Writer, r impactReport, jsonOut bool) error {
	if jsonOut {
		data, err := jsonutil.MarshalIndentWithNewline(r, "", "  ")
		if err != nil {
			return fmt.Errorf("marshal impact: %w", err)
		}
		if _, err := w.Write(data); err != nil {
			return fmt.Errorf("write impact JSON: %w", err)
		}
		return nil
	}
	fmt.Fprintf(w, "# Impact: %s (`%s`)\n\n", r.Target, r.NodeID)
	if len(r.Affected) == 0 {
		fmt.Fprintln(w, "_No structural neighbors or shared-checkpoint files found._")
		return nil
	}
	for _, n := range r.Affected {
		path := n.Path
		if path == "" {
			path = n.NodeID
		}
		fmt.Fprintf(w, "- **%s** _(%s)_ — %s", path, n.Type, n.Reason)
		if n.LastCheckpoint != "" {
			fmt.Fprintf(w, "; last in `%s`", n.LastCheckpoint)
			if n.LastAt != "" {
				fmt.Fprintf(w, " at %s", n.LastAt)
			}
		}
		fmt.Fprintln(w)
	}
	if r.Truncated {
		fmt.Fprintln(w, "\n_(output truncated; raise --max to see more)_")
	}
	return nil
}

