)

// newUnderstandHotspotsCmd builds `entire understand hotspots`.
//
// Scoring inputs per the spec: checkpoint count, distinct-agent count,
// rewrite count (approximated by checkpoint count for the POC), and a
// stub for centrality. Contradiction-flag scoring requires semantic data
// (intent/outcome summaries) and is not yet active in v1.
func newUnderstandHotspotsCmd() *cobra.Command {
	var jsonOut bool
	var topN int

	cmd := &cobra.Command{
		Use:   "hotspots",
		Short: "Rank files by checkpoint churn and agent diversity",
		Long: `Surface unstable parts of the codebase. Score is a deterministic mix of
checkpoint count and distinct-agent count over each file's touched_in edges.

Examples:
  entire understand hotspots
  entire understand hotspots --top 50 --json`,
		RunE: func(cmd *cobra.Command, _ []string) error {
			return runUnderstandHotspots(cmd.Context(), cmd.OutOrStdout(), jsonOut, topN)
		},
	}
	cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit JSON instead of markdown")
	cmd.Flags().IntVar(&topN, "top", 20, "Number of top hotspots to return")
	return cmd
}

type hotspot struct {
	NodeID         string  `json:"node_id"`
	Path           string  `json:"path"`
	CheckpointCount int    `json:"checkpoint_count"`
	DistinctAgents int     `json:"distinct_agents"`
	Score          float64 `json:"score"`
	LastCpID       string  `json:"last_cp,omitempty"`
	LastAt         string  `json:"last_at,omitempty"`
}

type hotspotsReport struct {
	Hotspots []hotspot `json:"hotspots"`
}

func runUnderstandHotspots(ctx context.Context, w io.Writer, jsonOut bool, topN int) error {
	q, err := loadQueryEnv(ctx)
	if err != nil {
		if errors.Is(err, errNoUnderstandCache) {
			fmt.Fprintln(w, err.Error())
			return nil
		}
		return err
	}

	report := hotspotsReport{}
	for fileID, cps := range q.touchedCps {
		n := q.byID[fileID]
		if n == nil || (n.Type != graph.NodeFile) {
			continue
		}
		// Distinct agents touching this file.
		agents := map[string]struct{}{}
		for _, cpID := range cps {
			cp := q.byID[cpID]
			if cp == nil {
				continue
			}
			if a, ok := cp.Attrs["agent"].(string); ok && a != "" {
				agents[a] = struct{}{}
			}
		}
		score := float64(len(cps)) + 0.5*float64(len(agents))
		hs := hotspot{
			NodeID:          fileID,
			Path:            n.Path,
			CheckpointCount: len(cps),
			DistinctAgents:  len(agents),
			Score:           score,
		}
		if cp := q.recentCheckpoint(fileID); cp != nil {
			hs.LastCpID = cp.Name
			if at, ok := cp.Attrs["created_at"].(string); ok {
				hs.LastAt = at
			}
		}
		report.Hotspots = append(report.Hotspots, hs)
	}
	sort.Slice(report.Hotspots, func(i, j int) bool {
		if report.Hotspots[i].Score != report.Hotspots[j].Score {
			return report.Hotspots[i].Score > report.Hotspots[j].Score
		}
		return report.Hotspots[i].Path < report.Hotspots[j].Path
	})
	if topN > 0 && len(report.Hotspots) > topN {
		report.Hotspots = report.Hotspots[:topN]
	}

	return emitHotspots(w, report, jsonOut)
}

func emitHotspots(w io.Writer, r hotspotsReport, jsonOut bool) error {
	if jsonOut {
		data, err := jsonutil.MarshalIndentWithNewline(r, "", "  ")
		if err != nil {
			return fmt.Errorf("marshal hotspots: %w", err)
		}
		if _, err := w.Write(data); err != nil {
			return fmt.Errorf("write hotspots JSON: %w", err)
		}
		return nil
	}
	if len(r.Hotspots) == 0 {
		fmt.Fprintln(w, "_No hotspots — no checkpoint history yet, or no files have been touched._")
		return nil
	}
	fmt.Fprintln(w, "# Hotspots")
	fmt.Fprintln(w)
	for i, h := range r.Hotspots {
		fmt.Fprintf(w, "%d. **%s** — score=%.1f (cps=%d, agents=%d)",
			i+1, h.Path, h.Score, h.CheckpointCount, h.DistinctAgents)
		if h.LastCpID != "" {
			fmt.Fprintf(w, "; last in `%s`", h.LastCpID)
			if h.LastAt != "" {
				fmt.Fprintf(w, " at %s", h.LastAt)
			}
		}
		fmt.Fprintln(w)
	}
	return nil
}

