// seedQueryCache builds a small graph with two files, a couple of symbols,
// and three checkpoints so tour/impact/examples/hotspots have realistic data.
func seedQueryCache(t *testing.T, dir string) {
	t.Helper()
	store := graph.NewStore(dir)

	structural := &graph.Slice{
		Nodes: []graph.Node{
			{ID: "repo:.", Type: graph.NodeRepo, Name: "."},
			{ID: "dir:cmd", Type: graph.NodeDirectory, Name: "cmd", Path: "cmd"},
			{ID: "file:cmd/main.go", Type: graph.NodeFile, Name: "main.go", Path: "cmd/main.go", Language: "go"},
			{ID: "file:cmd/other.go", Type: graph.NodeFile, Name: "other.go", Path: "cmd/other.go", Language: "go"},
			{ID: "file:README.md", Type: graph.NodeFile, Name: "README.md", Path: "README.md", Language: "markdown"},
			{ID: "sym:cmd/main.go:NewStore", Type: graph.NodeSymbol, SymbolKind: graph.SymbolFunction, Name: "NewStore", Path: "cmd/main.go", LineStart: 5, LineEnd: 8},
			{ID: "sym:cmd/other.go:Helper", Type: graph.NodeSymbol, SymbolKind: graph.SymbolFunction, Name: "Helper", Path: "cmd/other.go", LineStart: 1, LineEnd: 3},
		},
		Edges: []graph.Edge{
			{ID: "e1", From: "repo:.", To: "dir:cmd", Type: graph.EdgeContains},
			{ID: "e2", From: "dir:cmd", To: "file:cmd/main.go", Type: graph.EdgeContains},
			{ID: "e3", From: "dir:cmd", To: "file:cmd/other.go", Type: graph.EdgeContains},
			{ID: "e4", From: "repo:.", To: "file:README.md", Type: graph.EdgeContains},
			{ID: "e5", From: "file:cmd/main.go", To: "sym:cmd/main.go:NewStore", Type: graph.EdgeContains},
			{ID: "e6", From: "file:cmd/other.go", To: "sym:cmd/other.go:Helper", Type: graph.EdgeContains},
		},
	}
	history := &graph.Slice{
		Nodes: []graph.Node{
			{ID: "cp:111111111111", Type: graph.NodeCheckpoint, Name: "111111111111", Attrs: map[string]any{
				"created_at": time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC).Format(time.RFC3339),
				"agent":      "claude-code",
			}},
			{ID: "cp:222222222222", Type: graph.NodeCheckpoint, Name: "222222222222", Attrs: map[string]any{
				"created_at": time.Date(2026, 2, 1, 0, 0, 0, 0, time.UTC).Format(time.RFC3339),
				"agent":      "codex",
			}},
			{ID: "cp:333333333333", Type: graph.NodeCheckpoint, Name: "333333333333", Attrs: map[string]any{
				"created_at": time.Date(2026, 3, 1, 0, 0, 0, 0, time.UTC).Format(time.RFC3339),
				"agent":      "claude-code",
			}},
		},
		Edges: []graph.Edge{
			{ID: "h1", From: "cp:111111111111", To: "file:cmd/main.go", Type: graph.EdgeTouchedIn, Scope: graph.ScopeFileOwner},
			{ID: "h2", From: "cp:222222222222", To: "file:cmd/main.go", Type: graph.EdgeTouchedIn, Scope: graph.ScopeFileOwner},
			{ID: "h3", From: "cp:333333333333", To: "file:cmd/main.go", Type: graph.EdgeTouchedIn, Scope: graph.ScopeFileOwner},
			{ID: "h4", From: "cp:111111111111", To: "file:cmd/other.go", Type: graph.EdgeTouchedIn, Scope: graph.ScopeFileOwner},
			{ID: "h5", From: "cp:222222222222", To: "file:cmd/other.go", Type: graph.EdgeTouchedIn, Scope: graph.ScopeFileOwner},
		},
	}

	if err := store.WriteStructural(structural); err != nil {
		t.Fatalf("WriteStructural: %v", err)
	}
	if err := store.WriteHistory(history); err != nil {
		t.Fatalf("WriteHistory: %v", err)
	}
	if err := store.WriteManifest(&graph.Manifest{
		BuildID:          "seeded",
		BuiltAt:          time.Now().UTC(),
		StructuralStatus: "ok",
		HistoryStatus:    "ok",
		SemanticStatus:   graph.SemanticSkipped,
	}); err != nil {
		t.Fatalf("WriteManifest: %v", err)
	}
}

