package cli

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"sort"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/jsonutil"
	"github.com/entireio/cli/cmd/entire/cli/understand/graph"
	"github.com/spf13/cobra"
)

// newUnderstandPrimeCmd builds `entire understand prime [<path>...]`.
//
// Default behavior prints a bounded markdown priming packet to stdout (or
// JSON via --json). With --exec --agent <name> the packet is piped into
// the agent's interactive CLI as the first user message.
//
// Per the spec: this command is explicit, never runs in hooks, and the POC
// ships --exec support for claude-code only. Other agents are accepted but
// return a clear "not yet supported for --exec" message rather than silently
// printing the packet.
func newUnderstandPrimeCmd() *cobra.Command {
	var (
		jsonOut bool
		exec_    bool
		agentName string
		topHotspots int
	)

	cmd := &cobra.Command{
		Use:   "prime [<path>...]",
		Short: "Generate a priming packet for the next agent session",
		Long: `Build a structural + historical priming packet to orient an agent at the
start of a new session.

Modes:
  default        Print the markdown packet to stdout (use --json for machine output).
  --exec --agent claude-code
                 Launch the agent's CLI with the packet piped as stdin. Other
                 agents are accepted by name but produce a "not yet supported"
                 message rather than silently exec'ing.

Examples:
  entire understand prime
  entire understand prime cmd/entire/cli/understand
  entire understand prime --exec --agent claude-code`,
		RunE: func(cmd *cobra.Command, args []string) error {
			return runUnderstandPrime(cmd.Context(), cmd.OutOrStdout(), primeOptions{
				Targets:     args,
				JSONOut:     jsonOut,
				Exec:        exec_,
				AgentName:   agentName,
				TopHotspots: topHotspots,
			})
		},
	}
	cmd.Flags().BoolVar(&jsonOut, "json", false, "Emit JSON instead of markdown")
	cmd.Flags().BoolVar(&exec_, "exec", false, "Launch the named agent with the packet on stdin")
	cmd.Flags().StringVar(&agentName, "agent", "", "Agent name for --exec (POC supports claude-code only)")
	cmd.Flags().IntVar(&topHotspots, "top-hotspots", 8, "Number of hotspot rows to include in the packet")
	return cmd
}

type primeOptions struct {
	Targets     []string
	JSONOut     bool
	Exec        bool
	AgentName   string
	TopHotspots int
}

type primeTarget struct {
	Input  string         `json:"input"`
	NodeID string         `json:"node_id,omitempty"`
	Path   string         `json:"path,omitempty"`
	Type   string         `json:"type,omitempty"`
	LastCp string         `json:"last_cp,omitempty"`
	LastAt string         `json:"last_at,omitempty"`
	Notes  []string       `json:"notes,omitempty"`
}

type primePacket struct {
	Title    string        `json:"title"`
	Targets  []primeTarget `json:"targets,omitempty"`
	Hotspots []hotspot     `json:"hotspots,omitempty"`
	NoCache  bool          `json:"no_cache,omitempty"`
	Reason   string        `json:"reason,omitempty"`
}

// primeBinaryLookup is overridable from tests so --exec can be exercised
// without a real CLI on PATH. Default uses exec.LookPath.
var primeBinaryLookup = exec.LookPath

// primeRunner executes the prepared command. Tests can replace this with a
// no-op to verify --exec composition without actually launching anything.
var primeRunner = runPrimeExec

func runUnderstandPrime(ctx context.Context, w io.Writer, opts primeOptions) error {
	q, err := loadQueryEnv(ctx)
	if err != nil {
		if errors.Is(err, errNoUnderstandCache) {
			packet := primePacket{NoCache: true, Reason: err.Error(), Title: "no understand cache"}
			return emitPrimePacket(w, packet, opts)
		}
		return err
	}

	packet := buildPrimePacket(q, opts)
	if opts.Exec {
		return execPrime(w, packet, opts)
	}
	return emitPrimePacket(w, packet, opts)
}

func buildPrimePacket(q *queryEnv, opts primeOptions) primePacket {
	pkt := primePacket{Title: "Entire understand priming packet"}

	for _, raw := range opts.Targets {
		t := primeTarget{Input: raw}
		if node, err := q.resolveAreaNode(raw); err == nil {
			t.NodeID = node.ID
			t.Path = node.Path
			t.Type = string(node.Type)
			if cp := q.recentCheckpoint(node.ID); cp != nil {
				t.LastCp = cp.Name
				if at, ok := cp.Attrs["created_at"].(string); ok {
					t.LastAt = at
				}
			}
			// Inline up to 3 sibling-via-checkpoint files as notes so the
			// agent sees what tends to move with this target.
			shared := computeImpactSharedCheckpoints(q, node.ID)
			type entry struct {
				path  string
				count int
			}
			entries := make([]entry, 0, len(shared))
			for id, c := range shared {
				if n := q.byID[id]; n != nil {
					entries = append(entries, entry{path: n.Path, count: c})
				}
			}
			sort.Slice(entries, func(i, j int) bool { return entries[i].count > entries[j].count })
			for i, e := range entries {
				if i >= 3 {
					break
				}
				t.Notes = append(t.Notes, fmt.Sprintf("often co-touched with `%s` (%d shared cps)", e.path, e.count))
			}
		} else {
			t.Notes = []string{"unresolved target — run `entire understand build` if missing"}
		}
		pkt.Targets = append(pkt.Targets, t)
	}

	// Top hotspots regardless of targets — gives the agent a global picture.
	top := opts.TopHotspots
	if top <= 0 {
		top = 8
	}
	pkt.Hotspots = topHotspotsFor(q, top)
	return pkt
}

// topHotspotsFor reuses the hotspots scoring from understand_hotspots.go but
// inlines the loop here to avoid re-running the whole command and re-loading
// the graph.
func topHotspotsFor(q *queryEnv, n int) []hotspot {
	out := []hotspot{}
	for fileID, cps := range q.touchedCps {
		node := q.byID[fileID]
		if node == nil || node.Type != graph.NodeFile {
			continue
		}
		agents := map[string]struct{}{}
		for _, cpID := range cps {
			if cp := q.byID[cpID]; cp != nil {
				if a, ok := cp.Attrs["agent"].(string); ok && a != "" {
					agents[a] = struct{}{}
				}
			}
		}
		out = append(out, hotspot{
			NodeID:          fileID,
			Path:            node.Path,
			CheckpointCount: len(cps),
			DistinctAgents:  len(agents),
			Score:           float64(len(cps)) + 0.5*float64(len(agents)),
		})
	}
	sort.Slice(out, func(i, j int) bool {
		if out[i].Score != out[j].Score {
			return out[i].Score > out[j].Score
		}
		return out[i].Path < out[j].Path
	})
	if len(out) > n {
		out = out[:n]
	}
	return out
}

func emitPrimePacket(w io.Writer, p primePacket, opts primeOptions) error {
	if opts.JSONOut {
		data, err := jsonutil.MarshalIndentWithNewline(p, "", "  ")
		if err != nil {
			return fmt.Errorf("marshal prime packet: %w", err)
		}
		if _, err := w.Write(data); err != nil {
			return fmt.Errorf("write prime JSON: %w", err)
		}
		return nil
	}
	if p.NoCache {
		fmt.Fprintln(w, p.Reason)
		return nil
	}
	fmt.Fprintf(w, "# %s\n\n", p.Title)
	if len(p.Targets) > 0 {
		fmt.Fprintln(w, "## Targets")
		for _, t := range p.Targets {
			fmt.Fprintf(w, "- **%s**", t.Input)
			if t.Path != "" && t.Path != t.Input {
				fmt.Fprintf(w, " → `%s`", t.Path)
			}
			if t.Type != "" {
				fmt.Fprintf(w, " _(%s)_", t.Type)
			}
			if t.LastCp != "" {
				fmt.Fprintf(w, "; last in `%s`", t.LastCp)
				if t.LastAt != "" {
					fmt.Fprintf(w, " at %s", t.LastAt)
				}
			}
			fmt.Fprintln(w)
			for _, note := range t.Notes {
				fmt.Fprintf(w, "  - %s\n", note)
			}
		}
		fmt.Fprintln(w)
	}
	if len(p.Hotspots) > 0 {
		fmt.Fprintln(w, "## Hotspots")
		for i, h := range p.Hotspots {
			fmt.Fprintf(w, "%d. **%s** — score=%.1f (cps=%d, agents=%d)\n",
				i+1, h.Path, h.Score, h.CheckpointCount, h.DistinctAgents)
		}
	}
	return nil
}

// execPrime piped the packet into a known agent integration. POC ships
// claude-code only; other agents return a clear "not yet supported" message.
func execPrime(w io.Writer, packet primePacket, opts primeOptions) error {
	if opts.AgentName == "" {
		return errors.New("understand prime: --exec requires --agent <name>")
	}
	if opts.AgentName != "claude-code" {
		fmt.Fprintf(w, "agent %q is not yet supported for --exec; use the default packet output and pipe it manually.\n", opts.AgentName)
		return nil
	}
	binary, err := primeBinaryLookup("claude")
	if err != nil {
		return fmt.Errorf("claude CLI not on PATH: %w", err)
	}

	// Render the packet as markdown for piping.
	var sb strings.Builder
	if err := emitPrimePacket(&sb, packet, primeOptions{}); err != nil {
		return err
	}

	return primeRunner(binary, sb.String())
}

// runPrimeExec is the default --exec runner. It connects child stdin to the
// packet and child stdout/stderr to the user's terminal so the agent runs
// interactively.
func runPrimeExec(binary, stdin string) error {
	cmd := exec.Command(binary) //nolint:gosec // binary resolved via primeBinaryLookup
	cmd.Stdin = strings.NewReader(stdin)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	if err := cmd.Run(); err != nil {
		return fmt.Errorf("launch %s: %w", binary, err)
	}
	return nil
}

