	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	seedQueryCache(t, dir)
	t.Chdir(dir)
	paths.ClearWorktreeRootCache()

	var buf bytes.Buffer
	if err := runUnderstandPrime(context.Background(), &buf, primeOptions{
		Targets:     []string{"cmd/main.go"},
		TopHotspots: 5,
	}); err != nil {
		t.Fatalf("runUnderstandPrime: %v", err)
	}
	out := buf.String()
	for _, want := range []string{
		"# Entire understand priming packet",
		"## Targets",
		"cmd/main.go",
		"## Hotspots",
	} {
		if !strings.Contains(out, want) {
			t.Errorf("expected %q in output; got:\n%s", want, out)
		}
	}
}

func TestUnderstandPrime_JSON_Schema(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	seedQueryCache(t, dir)
	t.Chdir(dir)
	paths.ClearWorktreeRootCache()

	var buf bytes.Buffer
	if err := runUnderstandPrime(context.Background(), &buf, primeOptions{
		Targets:     []string{"cmd/main.go"},
		JSONOut:     true,
		TopHotspots: 3,
	}); err != nil {
		t.Fatalf("runUnderstandPrime: %v", err)
	}
	var got primePacket
	if err := json.Unmarshal(buf.Bytes(), &got); err != nil {
		t.Fatalf("decode JSON: %v\nraw=%s", err, buf.String())
	}
	if len(got.Targets) != 1 {
		t.Fatalf("Targets=%d; want 1", len(got.Targets))
	}
	tg := got.Targets[0]
	if tg.Input != "cmd/main.go" {
		t.Errorf("Target.Input=%q; want cmd/main.go", tg.Input)
	}
	if tg.NodeID != "file:cmd/main.go" {
		t.Errorf("Target.NodeID=%q; want file:cmd/main.go", tg.NodeID)
	}
	if tg.LastCp == "" {
		t.Errorf("Target.LastCp empty; expected most-recent cp annotation")
	}
	if len(got.Hotspots) == 0 {
		t.Errorf("Hotspots empty; expected top hotspots inline")
	}
}

