func TestUnderstandPrime_Exec_ClaudeCode_PipesPacket(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	seedQueryCache(t, dir)
	t.Chdir(dir)
	paths.ClearWorktreeRootCache()

	// Replace lookup + runner so the test never calls a real binary.
	origLookup := primeBinaryLookup
	origRunner := primeRunner
	t.Cleanup(func() {
		primeBinaryLookup = origLookup
		primeRunner = origRunner
	})
	primeBinaryLookup = func(name string) (string, error) {
		if name != "claude" {
			return "", errors.New("unexpected binary " + name)
		}
		return "/fake/claude", nil
	}
	var capturedBin, capturedStdin string
	primeRunner = func(bin, stdin string) error {
		capturedBin = bin
		capturedStdin = stdin
		return nil
	}

	var buf bytes.Buffer
	if err := runUnderstandPrime(context.Background(), &buf, primeOptions{
		Exec:      true,
		AgentName: "claude-code",
		Targets:   []string{"cmd/main.go"},
	}); err != nil {
		t.Fatalf("runUnderstandPrime exec: %v", err)
	}
	if capturedBin != "/fake/claude" {
		t.Errorf("exec binary=%q; want /fake/claude", capturedBin)
	}
	if !strings.Contains(capturedStdin, "Entire understand priming packet") {
		t.Errorf("stdin missing packet header; got:\n%s", capturedStdin)
	}
	if !strings.Contains(capturedStdin, "cmd/main.go") {
		t.Errorf("stdin missing target detail; got:\n%s", capturedStdin)
	}
}

