// makeStore returns a populated graph.Store rooted in t.TempDir() so the
// server has artifacts to read.
func makeStore(t *testing.T) *graph.Store {
	t.Helper()
	dir := t.TempDir()
	store := graph.NewStore(dir)
	if err := store.WriteManifest(&graph.Manifest{
		BuildID:          "test-build",
		BuiltAt:          time.Date(2026, 5, 5, 0, 0, 0, 0, time.UTC),
		StructuralStatus: "ok",
		HistoryStatus:    "ok",
		SemanticStatus:   graph.SemanticSkipped,
		NodeCount:        2,
		EdgeCount:        1,
	}); err != nil {
		t.Fatalf("WriteManifest: %v", err)
	}
	if err := store.WriteStructural(&graph.Slice{
		Nodes: []graph.Node{
			{ID: "file:main.go", Type: graph.NodeFile, Name: "main.go", Path: "main.go"},
		},
	}); err != nil {
		t.Fatalf("WriteStructural: %v", err)
	}
	if err := store.WriteHistory(&graph.Slice{
		Nodes: []graph.Node{
			{ID: "cp:abc", Type: graph.NodeCheckpoint, Name: "abc", Attrs: map[string]any{"agent": "claude-code"}},
		},
		Edges: []graph.Edge{
			{ID: "h1", From: "cp:abc", To: "file:main.go", Type: graph.EdgeTouchedIn, Scope: graph.ScopeFileOwner},
		},
	}); err != nil {
		t.Fatalf("WriteHistory: %v", err)
	}
	if err := store.WriteTimeline(&graph.Timeline{
		Events: []graph.TimelineEvent{
			{At: "2026-05-05T00:00:00Z", CheckpointID: "abc", Kind: "checkpoint", NodeIDs: []string{"file:main.go"}},
		},
	}); err != nil {
		t.Fatalf("WriteTimeline: %v", err)
	}
	return store
}

func newHandler(t *testing.T) (*Server, http.Handler) {
	t.Helper()
	store := makeStore(t)
	srv, err := New(store)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	mux := http.NewServeMux()
	srv.RegisterHandlers(mux)
	return srv, mux
}

func TestServer_RejectsMissingToken(t *testing.T) {
	t.Parallel()
	_, h := newHandler(t)
	rec := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodGet, "/api/manifest", http.NoBody)
	h.ServeHTTP(rec, req)
	if rec.Code != http.StatusUnauthorized {
		t.Errorf("status=%d; want 401", rec.Code)
	}
}

func TestServer_RejectsBadToken(t *testing.T) {
	t.Parallel()
	_, h := newHandler(t)
	rec := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodGet, "/api/manifest", http.NoBody)
	req.Header.Set("Authorization", "Bearer not-the-token")
	h.ServeHTTP(rec, req)
	if rec.Code != http.StatusUnauthorized {
		t.Errorf("status=%d; want 401", rec.Code)
	}
}

func TestServer_AcceptsCorrectBearer(t *testing.T) {
	t.Parallel()
	srv, h := newHandler(t)
	rec := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodGet, "/api/manifest", http.NoBody)
	req.Header.Set("Authorization", "Bearer "+srv.Token())
	h.ServeHTTP(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("status=%d; want 200", rec.Code)
	}
	body, _ := io.ReadAll(rec.Body)
	var m graph.Manifest
	if err := json.Unmarshal(body, &m); err != nil {
		t.Fatalf("decode manifest: %v", err)
	}
	if m.BuildID != "test-build" {
		t.Errorf("BuildID=%q; want test-build", m.BuildID)
	}
}

func TestServer_TokenInQueryStringIsRejected(t *testing.T) {
	t.Parallel()
	// Spec: never accept the token via query string. This regression guards
	// the contract — there is no code that reads ?token= today, but a future
	// change could naively add it.
	srv, h := newHandler(t)
	rec := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodGet, "/api/manifest?token="+srv.Token(), http.NoBody)
	// No Authorization header on purpose.
	h.ServeHTTP(rec, req)
	if rec.Code != http.StatusUnauthorized {
		t.Errorf("status=%d; want 401 (token in URL must not authenticate)", rec.Code)
	}
}

func TestServer_RejectsNonGetMethods(t *testing.T) {
	t.Parallel()
	srv, h := newHandler(t)
	rec := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodPost, "/api/manifest", strings.NewReader("{}"))
	req.Header.Set("Authorization", "Bearer "+srv.Token())
	h.ServeHTTP(rec, req)
	if rec.Code != http.StatusMethodNotAllowed {
		t.Errorf("status=%d; want 405", rec.Code)
	}
}

func TestServer_GraphIsReadOnlyShape(t *testing.T) {
	t.Parallel()
	srv, h := newHandler(t)
	rec := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodGet, "/api/graph", http.NoBody)
	req.Header.Set("Authorization", "Bearer "+srv.Token())
	h.ServeHTTP(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("status=%d; want 200", rec.Code)
	}
	body, _ := io.ReadAll(rec.Body)

	// The graph endpoint must NOT include any prompt/transcript bodies in
	// bulk. We canary on a few sentinel keys; if any of these appear here
	// we have accidentally widened the bulk-exposure surface.
	for _, banned := range []string{"\"prompt\"", "\"transcript\"", "transcript_body", "raw_transcript"} {
		if strings.Contains(string(body), banned) {
			t.Errorf("graph response contained banned key %q (transcript bulk-leak regression):\n%s", banned, string(body))
		}
	}
}

func TestServer_CheckpointDetailIsStub(t *testing.T) {
	t.Parallel()
	srv, h := newHandler(t)
	rec := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodGet, "/api/checkpoint/abc", http.NoBody)
	req.Header.Set("Authorization", "Bearer "+srv.Token())
	h.ServeHTTP(rec, req)
	if rec.Code != http.StatusNotFound {
		t.Errorf("status=%d; want 404 (v1 dashboard refuses to expose detail)", rec.Code)
	}
}

func TestServer_IndexBootstrapsToken(t *testing.T) {
	t.Parallel()
	srv, h := newHandler(t)
	rec := httptest.NewRecorder()
	req := httptest.NewRequest(http.MethodGet, "/", http.NoBody)
	h.ServeHTTP(rec, req)
	if rec.Code != http.StatusOK {
		t.Fatalf("index status=%d; want 200", rec.Code)
	}
	body := rec.Body.String()
	if !strings.Contains(body, "window.__entireUnderstandToken=") {
		t.Errorf("index missing bootstrap script tag")
	}
	if !strings.Contains(body, srv.Token()) {
		t.Errorf("index didn't include the per-launch token")
	}
	// Token must NOT appear inside a URL-shaped fragment in the body.
	if strings.Contains(body, "?token="+srv.Token()) {
		t.Errorf("token appeared in a URL — must only be in bootstrap state")
	}
}

func TestServer_FreshTokenPerInstance(t *testing.T) {
	t.Parallel()
	srvA, _ := newHandler(t)
	srvB, _ := newHandler(t)
	if srvA.Token() == "" || srvB.Token() == "" {
		t.Fatalf("empty token: a=%q b=%q", srvA.Token(), srvB.Token())
	}
	if srvA.Token() == srvB.Token() {
		t.Errorf("tokens collided: %q", srvA.Token())
	}
}

func TestServer_LiveListenerOnLoopback(t *testing.T) {
	t.Parallel()
	store := makeStore(t)
	srv, err := New(store)
	if err != nil {
		t.Fatalf("New: %v", err)
	}
	url, err := srv.Start(t.Context())
	if err != nil {
		t.Fatalf("Start: %v", err)
	}
	t.Cleanup(func() { _ = srv.Stop() })
	if !strings.HasPrefix(url, "http://127.0.0.1:") {
		t.Errorf("URL=%q; must bind to 127.0.0.1 only", url)
	}
}

