func seedReplayCache(t *testing.T, dir string) {
	t.Helper()
	store := graph.NewStore(dir)
	if err := store.WriteManifest(&graph.Manifest{
		BuildID: "rp", BuiltAt: time.Now().UTC(),
		StructuralStatus: "ok", HistoryStatus: "ok", SemanticStatus: graph.SemanticSkipped,
	}); err != nil {
		t.Fatalf("WriteManifest: %v", err)
	}
	if err := store.WriteTimeline(&graph.Timeline{
		Events: []graph.TimelineEvent{
			{At: "2026-01-01T00:00:00Z", CheckpointID: "aaaa", SessionID: "s1", Kind: "checkpoint", NodeIDs: []string{"file:a"}},
			{At: "2026-02-01T00:00:00Z", CheckpointID: "bbbb", SessionID: "s2", Kind: "checkpoint", NodeIDs: []string{"file:a", "file:b"}},
			{At: "2026-03-01T00:00:00Z", CheckpointID: "cccc", SessionID: "s2", Kind: "checkpoint", NodeIDs: []string{"file:b"}},
		},
	}); err != nil {
		t.Fatalf("WriteTimeline: %v", err)
	}
}

func TestUnderstandReplay_AllEvents(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	seedReplayCache(t, dir)
	t.Chdir(dir)
	paths.ClearWorktreeRootCache()

	var buf bytes.Buffer
	if err := runUnderstandReplay(context.Background(), &buf, replayOptions{JSONOut: true}); err != nil {
		t.Fatalf("runUnderstandReplay: %v", err)
	}
	var got replayReport
	if err := json.Unmarshal(buf.Bytes(), &got); err != nil {
		t.Fatalf("decode: %v\nraw=%s", err, buf.String())
	}
	if len(got.Events) != 3 {
		t.Errorf("Events=%d; want 3", len(got.Events))
	}
	// Events should be sorted by At ascending.
	if got.Events[0].CheckpointID != "aaaa" || got.Events[2].CheckpointID != "cccc" {
		t.Errorf("event order wrong: %+v", got.Events)
	}
}

func TestUnderstandReplay_FromTimestamp(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	seedReplayCache(t, dir)
