	testutil.InitRepo(t, dir)
	seedReplayCache(t, dir)
	t.Chdir(dir)
	paths.ClearWorktreeRootCache()

	var buf bytes.Buffer
	if err := runUnderstandReplay(context.Background(), &buf, replayOptions{
		From: "bbbb", JSONOut: true,
	}); err != nil {
		t.Fatalf("runUnderstandReplay: %v", err)
	}
	var got replayReport
	if err := json.Unmarshal(buf.Bytes(), &got); err != nil {
		t.Fatalf("decode: %v", err)
	}
	// "bbbb" matches itself directly via boundMatches.
	found := false
	for _, e := range got.Events {
		if e.CheckpointID == "bbbb" {
			found = true
		}
	}
	if !found {
		t.Errorf("expected bbbb in filtered events: %+v", got.Events)
	}
