// currentCheckpointHead returns the sha of the v1 metadata branch head, or
// "" when the branch doesn't exist or the repo can't be opened. Best-effort
// only — stale detection silently degrades to "fresh" when uncertain.
func currentCheckpointHead(ctx context.Context) string {
	repo, err := strategy.OpenRepository(ctx)
	if err != nil {
		return ""
	}
	refName := plumbing.ReferenceName("refs/heads/" + paths.MetadataBranchName)
	ref, err := repo.Reference(refName, true)
	if err != nil || ref == nil {
		return ""
	}
	return ref.Hash().String()
}

// staleNotice returns a one-line user-facing string suitable for surfacing
// above command output when the underlying cache is stale. Empty when fresh.
func (q *queryEnv) staleNotice() string {
	if q == nil || !q.stale {
		return ""
	}
	return "_(cache may be stale — checkpoint head has moved since the last build; run `entire understand build` to refresh)_"
}

// semanticUnavailableNotice returns a one-line hint when the manifest's
// SemanticStatus is not OK. Spec: "commands whose value is mostly semantic
// (tour, examples, parts of prime, contradiction wording in impact) should
// say that semantic enrichment is unavailable and continue with the
// structural/history subset".
func (q *queryEnv) semanticUnavailableNotice() string {
	if q == nil || q.manifest == nil {
		return ""
	}
	if q.manifest.SemanticStatus == graph.SemanticOK && q.manifest.SemanticReason == "" {
		return ""
	}
	reason := string(q.manifest.SemanticStatus)
	if q.manifest.SemanticReason != "" {
		reason += ": " + q.manifest.SemanticReason
	}
	return "_(semantic enrichment unavailable [" + reason + "]; falling back to structural/history only)_"
}

