		}
	}
	if hint := agentFlipHint(q, n.ID); hint != "" {
		nb.ConflictHint = hint
	}
	return nb
}

// agentFlipHint returns "agent-flip: <recent> != <primary>" when the most
// recent checkpoint touching nodeID was authored by an agent that is NOT
// the most-frequent author of the same file. This is a deterministic
// proxy for "different agent redoing or reverting prior work" and serves
// the spec's "deterministic conflict hints from structural direction
// changes" requirement until semantic synthesis can word it richer.
func agentFlipHint(q *queryEnv, nodeID string) string {
	cps := q.touchedCps[nodeID]
	if len(cps) < 2 {
		return ""
	}
	counts := map[string]int{}
	var mostRecentAgent, mostRecentAt string
	for _, cpID := range cps {
		cp := q.byID[cpID]
		if cp == nil {
			continue
		}
		agent, _ := cp.Attrs["agent"].(string)
		if agent == "" {
			continue
		}
		counts[agent]++
		at, _ := cp.Attrs["created_at"].(string)
		if at > mostRecentAt {
			mostRecentAt = at
			mostRecentAgent = agent
		}
	}
	if len(counts) < 2 || mostRecentAgent == "" {
		return ""
	}
	primary := ""
	bestN := 0
	for agent, n := range counts {
		if n > bestN || (n == bestN && agent < primary) {
			primary = agent
			bestN = n
		}
	}
	if primary == "" || primary == mostRecentAgent {
		return ""
	}
	return "agent-flip: most recent touch by " + mostRecentAgent + ", primary author " + primary
}

