func TestUnderstandTour_DashboardFragment(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	seedQueryCache(t, dir)
	t.Chdir(dir)
	paths.ClearWorktreeRootCache()

	var buf bytes.Buffer
	if err := runUnderstandTour(context.Background(), &buf, "dir:cmd", true, true, 25); err != nil {
		t.Fatalf("runUnderstandTour --dashboard: %v", err)
	}
	var got tourReport
	if err := json.Unmarshal(buf.Bytes(), &got); err != nil {
		t.Fatalf("decode JSON: %v\nraw=%s", err, buf.String())
	}
	if got.DashboardFragment != "#area=dir:cmd" {
		t.Errorf("DashboardFragment=%q; want #area=dir:cmd", got.DashboardFragment)
	}
	if len(got.Stops) != 0 {
		t.Errorf("Stops=%d; want 0 (dashboard mode short-circuits the walk)", len(got.Stops))
	}
}

func TestUnderstandImpact_AgentFlipHint(t *testing.T) {
	dir := t.TempDir()
	testutil.InitRepo(t, dir)
	seedQueryCache(t, dir)
	t.Chdir(dir)
	paths.ClearWorktreeRootCache()

	var buf bytes.Buffer
	if err := runUnderstandImpact(context.Background(), &buf, "cmd/main.go", true, 30); err != nil {
		t.Fatalf("runUnderstandImpact: %v", err)
	}
	var got impactReport
	if err := json.Unmarshal(buf.Bytes(), &got); err != nil {
		t.Fatalf("decode JSON: %v", err)
	}
	// cmd/other.go has cps from claude-code (#1) and codex (#2). Most recent
	// is codex, primary is split — claude-code and codex each touched once.
	// On a tie the alphabetic-first agent wins primary; both touched once,
	// so primary=claude-code (alphabetic). Most recent != primary →
	// agent-flip hint should fire.
	for _, n := range got.Affected {
		if n.Path == "cmd/other.go" {
			if n.ConflictHint == "" {
				t.Errorf("cmd/other.go missing agent-flip hint; got %+v", n)
			}
			if !strings.Contains(n.ConflictHint, "agent-flip") {
				t.Errorf("ConflictHint=%q; want agent-flip prefix", n.ConflictHint)
			}
		}
	}
}

